#include <stdio.h>

int main() {
    int decimal_num;
    scanf("%d", &decimal_num);

    if (decimal_num == 0) {
        printf("Binary equivalent of 0 is: 0\n");
        return 0;
    }

    long long binary_num = 0;
    int base = 1;
    int temp = decimal_num;

    while (temp > 0) {
        int remainder = temp % 2;
        temp /= 2;
        binary_num += remainder * base;
        base *= 10;
    }

    printf("Binary equivalent of %d is: %lld\n", decimal_num, binary_num);
    return 0;
}

