    insert(10);
    insert(20);
    insert(30);
    display();
    return 0;
}

#include <stdio.h>

#define MAX_SIZE 5

int stack[MAX_SIZE];
int top = -1;

void push(int data) {
    if (top == MAX_SIZE - 1) {
        printf("Stack Overflow! Cannot push %d.\n", data);
    } else {
        top++;
        stack[top] = data;
        printf("Element %d pushed to Stack.\n", data);
    }
}

int pop() {
    if (top == -1) {
        printf("Stack Underflow! Stack is empty.\n");
        return -1;
    } else {
        int data = stack[top];
        top--;
        return data;
    }
}

int main() {
    push(10);
    push(20);
    printf("Popped element: %d\n", pop());
    push(30);
    printf("Popped element: %d\n", pop());
    printf("Popped element: %d\n", pop());
    printf("Popped element: %d\n", pop());
    return 0;
}

#include <stdio.h>

#define MAX_SIZE 5

int queue[MAX_SIZE];
int front = -1, rear = -1;

void enqueue(int data) {
    if (rear == MAX_SIZE - 1) {
        printf("Queue Overflow! Cannot enqueue %d.\n", data);
    } else {
        if (front == -1) front = 0;
        rear++;
        queue[rear] = data;
        printf("Element %d enqueued to Queue.\n", data);
    }
}

int dequeue() {
    if (front == -1 || front > rear) {
        printf("Queue Underflow! Queue is empty.\n");
        return -1;
    } else {
        int data = queue[front];
        front++;
        if (front > rear) front = rear = -1;
        return data;
    }
}

int main() {
    enqueue(10);
    enqueue(20);
    printf("Dequeued element: %d\n", dequeue());
    enqueue(30);
    printf("Dequeued element: %d\n", dequeue());
    printf("Dequeued element: %d\n", dequeue());
    printf("Dequeued element: %d\n", dequeue());
    return 0;
}

#include <stdio.h>

int recursiveBinarySearch(int arr[], int low, int high, int key) {
    if (low <= high) {
        int mid = low + (high - low) / 2;
        if (arr[mid] == key) return mid;
        if (arr[mid] > key) return recursiveBinarySearch(arr, low, mid - 1, key);
        return recursiveBinarySearch(arr, mid + 1, high, key);
    }
    return -1;
}

int main() {
    int arr[] = {2, 5, 8, 12, 16, 23, 38, 56, 72, 91};
    int n = 10;
    int key = 23;

    int result = recursiveBinarySearch(arr, 0, n - 1, key);
    if (result != -1) {
        printf("Element %d found at index %d.\n", key, result);
    } else {
        printf("Element %d not found in the array.\n", key);
    }

    key = 99;
    result = recursiveBinarySearch(arr, 0, n - 1, key);
    if (result == -1) {
        printf("Element %d not found in the array.\n", key);
    }
    return 0;
}

#include <stdio.h>

void bubbleSort(int arr[], int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                int temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }
}

void printArray(int arr[], int size) {
    for (int i = 0; i < size; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");
}

int main() {
    int arr[] = {64, 34, 25, 12, 22, 11, 90};
    int n = 7;

    printf("Unsorted array: ");
    printArray(arr, n);
    bubbleSort(arr, n);
    printf("Sorted array (Bubble Sort): ");
    printArray(arr, n);
    return 0;
}

#include <stdio.h>

int main() {
    int num1, num2, a, b, temp, gcd, lcm;

    // Prompt and read the two integers
    printf("Enter two positive integers: ");
    scanf("%d %d", &num1, &num2);

    // Make copies for GCD calculation
    a = num1;
    b = num2;

    // --- GCD Calculation (Euclidean Algorithm) ---
    while (b != 0) {
        temp = b;
        b = a % b;
        a = temp;
    }
    gcd = a; // GCD is stored in 'a'

    // --- LCM Calculation ---
    // Formula: LCM(a, b) = (|a * b|) / GCD(a, b)
    lcm = (num1 * num2) / gcd;

    // Print the results
    printf("\nGCD of %d and %d is %d\n", num1, num2, gcd);
    printf("LCM of %d and %d is %d\n", num1, num2, lcm);

    return 0;
}

#include <stdio.h>
#include <stdlib.h> // Required for malloc and free

int main() {
    int n, i, sum = 0;
    int *arr; // Pointer to hold the base address of the dynamic array

    // 1. Prompt and read the number of elements
    printf("Enter the number of elements: ");
    if (scanf("%d", &n) != 1 || n <= 0) {
        printf("Invalid input for the number of elements.\n");
        return 1;
    }

    // 2. Dynamically allocate memory for n integers
    arr = (int*)malloc(n * sizeof(int)); 

    // 3. Check for allocation failure
    if (arr == NULL) {
        printf("Memory allocation failed!\n");
        return 1;
    }

    // 4. Read the elements
    printf("Enter %d integers: ", n);
    for (i = 0; i < n; i++) {
        if (scanf("%d", &arr[i]) != 1) {
            printf("Error reading element.\n");
            free(arr);
            return 1;
        }
        sum += arr[i]; // Calculate the sum while reading
    }

    // 5. Print the result
    printf("\nThe sum of the elements is: %d\n", sum);

    // 6. Free the allocated memory
    free(arr);
    printf("Memory freed successfully.\n");

    return 0;
}

