#include <stdio.h>

#define ROWS 3
#define COLS 2

// Function to print a matrix
void printMatrix(int matrix[ROWS][COLS], int r, int c) {
    for (int i = 0; i < r; i++) {
        for (int j = 0; j < c; j++) {
            printf("%d ", matrix[i][j]);
        }
        printf("\n");
    }
}

int main() {
    // Original Matrix (3x2)
    int A[ROWS][COLS] = {
        {1, 2},
        {3, 4},
        {5, 6}
    };

    // Transposed Matrix will be 2x3 (COLS x ROWS)
    int B[COLS][ROWS]; 

    printf("Original Matrix (%dx%d):\n", ROWS, COLS);
    // Note: This call to printMatrix is slightly simplified as C requires fixed dimensions for functions
    // The dimensions are used to print the labels correctly.
    for (int i = 0; i < ROWS; i++) {
        for (int j = 0; j < COLS; j++) {
            printf("%d ", A[i][j]);
        }
        printf("\n");
    }

    // --- Transpose Calculation ---
    for (int i = 0; i < ROWS; i++) { // i is the row index of A
        for (int j = 0; j < COLS; j++) { // j is the col index of A
            // A[i][j] becomes B[j][i]
            B[j][i] = A[i][j]; 
        }
    }
    // --- End of Transpose Calculation ---

    printf("\nTransposed Matrix (%dx%d):\n", COLS, ROWS);
    // Note: When printing B, the dimensions are COLS x ROWS
    for (int i = 0; i < COLS; i++) {
        for (int j = 0; j < ROWS; j++) {
            printf("%d ", B[i][j]);
        }
        printf("\n");
    }

    return 0;
}

#include <stdio.h>
#include <string.h> // For strlen (allowed here to get lengths, but copy/search is manual)

// Function to implement Naive String Search
int naiveSearch(const char *haystack, const char *needle) {
    int n = strlen(haystack); // Length of main string
    int m = strlen(needle);    // Length of pattern

    // Outer loop: iterate through all possible starting positions in haystack
    for (int i = 0; i <= n - m; i++) {
        int j;

        // Inner loop: check for pattern match starting at index i
        for (j = 0; j < m; j++) {
            if (haystack[i + j] != needle[j]) {
                break; // Mismatch found, break inner loop and move to next starting position i
            }
        }

        // If the inner loop completed (j reached m), a match is found
        if (j == m) {
            return i; // Return the starting index
        }
    }

    return -1; // Pattern not found
}

int main() {
    const char *haystack = "ABABDABACDABABCABAB";
    const char *needle = "ABABCABAB";

    int result = naiveSearch(haystack, needle);

    if (result != -1) {
        printf("Pattern found at index %d.\n", result);
    } else {
        printf("Pattern not found.\n");
    }

    // Another test case
    const char *needle2 = "XYZ";
    result = naiveSearch(haystack, needle2);
    if (result == -1) {
        printf("Pattern not found.\n");
    }

    return 0;
}

#include <stdio.h>
#include <string.h>
#include <stdlib.h> // For malloc/free if necessary, but not strictly needed here

#define MAX_WORDS 20

// Function to reverse the order of words
void reverseWords(char *str) {
    // Array to store pointers to each word
    char *words[MAX_WORDS];
    int word_count = 0;

    // Use strtok to tokenize the string (words separated by space)
    char *token = strtok(str, " ");
    while (token != NULL && word_count < MAX_WORDS) {
        words[word_count++] = token; // Store the pointer to the word
        token = strtok(NULL, " "); // Get the next token
    }

    // Print the words in reverse order
    printf("Reversed Words: ");
    for (int i = word_count - 1; i >= 0; i--) {
        printf("%s", words[i]);
        if (i > 0) {
            printf(" "); // Print space between words
        }
    }
    printf("\n");
}

int main() {
    // Note: strtok modifies the original string, so we use a char array.
    char str[] = "Gemini is a helpful assistant";  

    printf("Original String: %s\n", str);

    // We need a temporary copy because strtok modifies str
    char temp_str[100];
    strcpy(temp_str, str);  

    reverseWords(temp_str);

    return 0;
}

#include <stdio.h>

// Recursive function to solve Tower of Hanoi
// n: number of disks
// source, auxiliary, destination: names of the pegs
void towerOfHanoi(int n, char source, char destination, char auxiliary) {
    // Base Case: Only one disk to move
    if (n == 1) {
        printf("Move disk 1 from %c to %c\n", source, destination);
        return;
    }

    // Step 1: Move n-1 disks from Source to Auxiliary, using Destination
    towerOfHanoi(n - 1, source, auxiliary, destination);

    // Step 2: Move the largest disk n from Source to Destination
    printf("Move disk %d from %c to %c\n", n, source, destination);

    // Step 3: Move n-1 disks from Auxiliary to Destination, using Source
    towerOfHanoi(n - 1, auxiliary, destination, source);
}

int main() {
    int num_disks = 3; // The number of disks
    char peg_A = 'A';  // Source peg
    char peg_B = 'B';  // Auxiliary peg
    char peg_C = 'C';  // Destination peg

    printf("Tower of Hanoi with %d disks:\n", num_disks);
    towerOfHanoi(num_disks, peg_A, peg_C, peg_B);

    return 0;
}

#include <stdio.h>
#include <string.h>

// Recursive function to generate all combinations
// set: The original input string/set of characters
// combination: The current combination being built
// index: The current character index being considered
void generateCombinations(const char *set, char *combination, int index) {
    int n = strlen(set);

    // Base Case: If all characters have been considered
    if (index == n) {
        // The combination string needs a null terminator for printing
        printf("{%s}\n", combination);  
        return;
    }

    // 1. Recursive Step (Include the current character)
    int len = strlen(combination);
    combination[len] = set[index]; // Add the character
    combination[len + 1] = '\0';  // Null-terminate the new combination
    generateCombinations(set, combination, index + 1);

    // 2. Recursive Step (Exclude the current character - Backtrack)
    combination[len] = '\0'; // Remove the last added character (backtrack)
    generateCombinations(set, combination, index + 1);
}

int main() {
    const char *set = "ABC";

    // We need an array to build the combination string. Max size is set length + 1 (\0).
    char combination[4] = "";  

    printf("Combinations for set: %s\n", set);

    // Start the generation with an empty combination and index 0
    generateCombinations(set, combination, 0);  

    return 0;
}

#include <stdio.h>
#include <string.h>

// Utility function to swap two characters
void swap(char *x, char *y) {
    char temp;
    temp = *x;
    *x = *y;
    *y = temp;
}

// Recursive function to generate permutations
// str: The string array
// l: Starting index of the current substring
// r: Ending index of the current substring
void permute(char *str, int l, int r) {
    int i;
    // Base Case: When the starting index reaches the end, a permutation is complete
    if (l == r) {
        printf("%s\n", str);
    } else {
        // Recursive Step: Iterate from the start index to the end
        for (i = l; i <= r; i++) {
            // 1. Swap: Fix the character str[i] at the current position str[l]
            swap((str + l), (str + i));

            // 2. Recurse: Permute the remaining substring (from l+1 to r)
            permute(str, l + 1, r);

            // 3. Backtrack: Swap back to restore the original order 
            // This is CRITICAL to ensure all permutations are generated correctly
            swap((str + l), (str + i));
        }
    }
}

int main() {
    // Note: Must use a char array to allow modification (swapping)
    char str[] = "ABC";  
    int n = strlen(str);

    printf("Permutations of %s:\n", str);
    permute(str, 0, n - 1);

    return 0;
}

#include <stdio.h>
