#define ROWS 3
#define COLS 3

// Directions: {row_change, col_change} for Up, Down, Left, Right
int dRow[] = {-1, 1, 0, 0};
int dCol[] = {0, 0, -1, 1};

// Global visited array (initialized to false/0)
bool visited[ROWS][COLS] = {false};

// Check if a cell is within grid boundaries
bool isValid(int row, int col) {
    return (row >= 0 && row < ROWS && col >= 0 && col < COLS);
}

// Depth First Search function
void DFS(int row, int col) {
    // 1. Mark the current cell as visited and print
    visited[row][col] = true;
    printf("Visiting (%d, %d)\n", row, col);

    // 2. Explore all 4 neighbors
    for (int i = 0; i < 4; i++) {
        int newRow = row + dRow[i];
        int newCol = col + dCol[i];

        // Check if the neighbor is valid and not yet visited
        if (isValid(newRow, newCol) && !visited[newRow][newCol]) {
            DFS(newRow, newCol); // Recurse: Dive deeper
        }
    }
}

int main() {
    int startRow = 0;
    int startCol = 0;

    printf("DFS Traversal starting from (%d, %d):\n", startRow, startCol);

    // Start the DFS from the specified coordinate
    DFS(startRow, startCol);

    return 0;
}

#include <stdio.h>

#define N 5 // Number of elements (0 to N-1)

int parent[N];

// Initializes each element as a set containing only itself
void initializeSets() {
    for (int i = 0; i < N; i++) {
        parent[i] = i;  
    }
}

// Find the representative (root) of the set containing element i
int find(int i) {
    // Stop condition: if element is its own parent, it's the root
    if (parent[i] == i) {
        return i;
    }
    // Recursive call to find the root
    return find(parent[i]);
}

// Union (unite) the sets containing elements i and j
void unite(int i, int j) {
    // Find the roots/representatives of i and j
    int root_i = find(i);
    int root_j = find(j);

    // If they are not already in the same set
    if (root_i != root_j) {
        // Simple Union: make root_j the parent of root_i
        parent[root_i] = root_j;
        printf("Set of %d and %d united.\n", i, j);
    } else {
        printf("%d and %d are already in the same set.\n", i, j);
    }
}

int main() {
    initializeSets();
    printf("Initial sets: {0}, {1}, {2}, {3}, {4}\n\n");

    unite(0, 1);
    unite(2, 3);

    printf("Representative of 1 is %d\n", find(1));
    printf("Representative of 4 is %d\n", find(4));

    unite(1, 4);

    printf("Representative of 0 is %d\n", find(0)); // Should be same as 4

    return 0;
}

