// Utility function to reverse a segment of an array
void reverse(int arr[], int start, int end) {
    while (start < end) {
        int temp = arr[start];
        arr[start] = arr[end];
        arr[end] = temp;
        start++;
        end--;
    }
}

// Function to rotate array to the right by k steps (in-place)
void rotateArrayRight(int arr[], int n, int k) {
    // Handle the case where k is larger than n or k is 0
    k = k % n;
    if (k == 0) return;

    // The segment to be moved to the front has size k. 
    // The main segment has size n-k.
    int break_point = n - k;

    // 1. Reverse the first (n-k) elements
    reverse(arr, 0, break_point - 1);

    // 2. Reverse the last k elements
    reverse(arr, break_point, n - 1);

    // 3. Reverse the entire array
    reverse(arr, 0, n - 1);
}

// Function to print the array
void printArray(int arr[], int size) {
    for (int i = 0; i < size; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");
}

int main() {
    int arr[] = {1, 2, 3, 4, 5, 6, 7};
    int n = sizeof(arr) / sizeof(arr[0]);
    int k = 3; // Number of right rotations

    printf("Original Array: ");
    printArray(arr, n);

    rotateArrayRight(arr, n, k);

    printf("Array after %d right rotations: ", k);
    printArray(arr, n);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

// Function to solve the Josephus Problem using array simulation
int josephus(int n, int k) {
    // Use a list/array to hold the person positions (1 to n)
    int *people = (int*)malloc(n * sizeof(int));
    if (people == NULL) return -1;

    for (int i = 0; i < n; i++) {
        people[i] = i + 1; // 1-based indexing for people
    }

    int current_index = 0; // The index of the first person to be counted from
    int remaining = n;

    // Loop until only one person remains
    while (remaining > 1) {
        // Calculate the index of the person to be eliminated
        // (k-1) because we are counting k steps from the current_index (0-based)
        current_index = (current_index + k - 1) % remaining;

        // The person at current_index is eliminated.
        // We simulate removal by shifting all subsequent elements left.
        for (int i = current_index; i < remaining - 1; i++) {
            people[i] = people[i + 1];
        }

        remaining--; // One person is eliminated

        // The next count starts from the person who moved into the current_index slot.
        // The new current_index will be 0 if the eliminated person was the last one.
        current_index = current_index % remaining;
    }

    int survivor = people[0];
    free(people);
    return survivor;
}

int main() {
    int N = 7; // Number of people
    int K = 3; // Step

    int survivor_pos = josephus(N, K);

    if (survivor_pos != -1) {
        printf("The survivor is at position %d\n", survivor_pos);
    } else {
        printf("Error in calculation.\n");
    }

    return 0;
}

