// Function to return the maximum of two integers
int max(int a, int b) {
    return (a > b) ? a : b;
}

// Returns the maximum value that can be put in a knapsack of capacity W
int knapSack(int W, int wt[], int val[], int n) {
    // K[i][w] is the max value using first i items and capacity w
    int K[n + 1][W + 1];

    // Build table K[][] in a bottom-up manner
    for (int i = 0; i <= n; i++) {
        for (int w = 0; w <= W; w++) {
            if (i == 0 || w == 0) {
                // Base case: 0 items or 0 capacity means 0 value
                K[i][w] = 0;
            }  
            // Case 1: If weight of item i is more than current knapsack capacity w, skip it
            else if (wt[i - 1] > w) {
                K[i][w] = K[i - 1][w];
            }  
            // Case 2: Take the max of (skipping item i, OR taking item i + max value of remaining capacity)
            else {
                K[i][w] = max(K[i - 1][w], val[i - 1] + K[i - 1][w - wt[i - 1]]);
            }
        }
    }

    return K[n][W]; // The final max value
}

int main() {
    int val[] = {60, 100, 120}; // Values of items
    int wt[] = {10, 20, 30};    // Weights of items
    int W = 50;              // Knapsack capacity
    int n = sizeof(val) / sizeof(val[0]); // Number of items

    int max_value = knapSack(W, wt, val, n);

    printf("Maximum value in Knapsack: %d\n", max_value);

    return 0;
}

