// Function to find the length of LCS
int lcsLength(const char *X, const char *Y, int m, int n) {
    // Dynamically allocate 2D array L[m+1][n+1]
    int **L = (int**)malloc((m + 1) * sizeof(int*));
    if (L == NULL) return 0;
    for (int i = 0; i <= m; i++) {
        L[i] = (int*)calloc(n + 1, sizeof(int));
        if (L[i] == NULL) { /* Handle memory error and clean up */ return 0; }
    }

    // Build L[m+1][n+1] in a bottom-up fashion
    for (int i = 0; i <= m; i++) {
        for (int j = 0; j <= n; j++) {
            if (i == 0 || j == 0) {
                L[i][j] = 0;
            }  
            // Case 1: Characters match
            else if (X[i - 1] == Y[j - 1]) {
                L[i][j] = 1 + L[i - 1][j - 1];
            }  
            // Case 2: Characters don't match
            else {
                L[i][j] = max(L[i - 1][j], L[i][j - 1]);
            }
        }
    }

    int result = L[m][n];

    // Free the dynamically allocated memory
    for (int i = 0; i <= m; i++) {
        free(L[i]);
    }
    free(L);

    return result;
}

int main() {
    const char *S1 = "AGGTAB";
    const char *S2 = "GXTXAYB";

    int m = strlen(S1);
    int n = strlen(S2);

    int length = lcsLength(S1, S2, m, n);

    printf("Length of LCS is %d\n", length);

    return 0;
}

