// Function to check if a number is a power of 2 using bit manipulation
// True if N is a power of 2, False otherwise
int isPowerOfTwo(int n) {
    // A power of 2 has only one set bit. N & (N - 1) clears the least significant set bit.
    // If N is a power of 2, then N & (N - 1) will be 0. We must also check N > 0.
    return (n > 0) && ((n & (n - 1)) == 0);
}

// Function to count the number of set bits (1s) using Brian Kernighan's Algorithm
int countSetBits(int n) {
    int count = 0;
    while (n > 0) {
        n &= (n - 1); // Clears the least significant set bit
        count++;
    }
    return count;
}

void printResults(int num) {
    printf("%d is a power of 2 (%s).\n", num, isPowerOfTwo(num) ? "True" : "False");
    printf("Number of set bits in %d is %d\n", num, countSetBits(num));
}

int main() {
    int num1 = 16; // Binary: 10000 (Power of 2)
    int num2 = 13; // Binary: 1101 (Not a Power of 2)

    printResults(num1);
    printResults(num2);

    return 0;
}

