#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define N 4 // For the 4-Queens problem

// Array to store the solution: pos[i] = column of the queen in row i
int board[N]; 

// Function to print the solution board
void printSolution() {
    printf("Solution found:\n");
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            if (board[i] == j) {
                printf("Q "); // Queen is at (i, j)
            } else {
                printf(". "); // Empty square
            }
        }
        printf("\n");
    }
    printf("\n");
}

// Function to check if a queen can be safely placed at board[row][col]
bool isSafe(int row, int col) {
    // Check all previous rows (0 to row-1)
    for (int prev_row = 0; prev_row < row; prev_row++) {
        // 1. Check for column conflict (Vertical)
        if (board[prev_row] == col) {
            return false;
        }
        // 2. Check for diagonal conflict (|row - prev_row| == |col - board[prev_row]|)
        if (abs(prev_row - row) == abs(board[prev_row] - col)) {
            return false;
        }
    }
    return true; // The position is safe
}

// Main recursive backtracking function
bool solveNQueens(int row) {
    // Base Case: All queens are placed successfully
    if (row >= N) {
        printSolution();
        return true; // Returning true to find only one solution
    }

    // Try placing a queen in every column of the current row
    for (int col = 0; col < N; col++) {
        if (isSafe(row, col)) {
            // Place the queen (move to the next state)
            board[row] = col; 

            // Recurse for the next row
            if (solveNQueens(row + 1)) {
                return true; // Solution found down this path
            }

            // Backtrack: If placing the queen here didn't lead to a solution, 
            // the board[row] assignment is effectively undone 
            // when the loop moves to the next column. The loop proceeds to the next column.
        }
    }

    return false; // No safe place in this row
}

int main() {
    printf("N-Queens Solution for N=%d:\n", N);

    // Initialize board array to a safe value (though not strictly necessary)
    for (int i = 0; i < N; i++) {
        board[i] = -1;  
    }

    if (solveNQueens(0) == false) {
        printf("Solution does not exist.\n");
    }

    return 0;
}

#include <stdio.h>
#include <stdbool.h>

#define V 4 // Number of vertices

// Global array to store the state of each vertex
// 0: White (Unvisited)
// 1: Gray (In recursion stack / being visited)
// 2: Black (Finished processing)
int color[V]; 

// Adjacency Matrix for the Directed Graph
int graph[V][V] = {
    {0, 1, 0, 0}, // 0 -> 1
    {0, 0, 1, 0}, // 1 -> 2
    {0, 0, 0, 1}, // 2 -> 3
    {1, 0, 0, 0}  // 3 -> 0 (Forms a cycle)
};

// DFS function for cycle detection
bool DFS_cycle_detection(int u) {
    // 1. Mark the current node as Gray (in recursion stack)
    color[u] = 1;

    // 2. Recur for all the vertices adjacent to this vertex
    for (int v = 0; v < V; v++) {
        // If there is an edge from u to v
        if (graph[u][v] == 1) {

            // Case 1: If v is Gray, we found a back edge (a cycle)
            if (color[v] == 1) {
                return true;  
            }

            // Case 2: If v is White, recurse
            if (color[v] == 0) {
                if (DFS_cycle_detection(v)) {
                    return true; // Cycle found in the recursive call
                }
            }

            // Case 3: If v is Black, it's a cross-edge or forward-edge, skip it.
        }
    }

    // 3. Mark the current node as Black (finished processing)
    color[u] = 2;

    return false; // No cycle found from this vertex
}

// Main function to check for cycles in the entire graph
bool hasCycle() {
    // Initialize all vertices to White (0)
    for (int i = 0; i < V; i++) {
        color[i] = 0;
    }

    // Check all vertices, as the graph might be disconnected
    for (int i = 0; i < V; i++) {
        if (color[i] == 0) { // If the vertex is unvisited
            if (DFS_cycle_detection(i)) {
                return true;
            }
        }
    }
    return false;
}

int main() {
    if (hasCycle()) {
        printf("Cycle detected in the graph.\n", 1);
    } else {
        printf("No cycle detected in the graph.\n", 0);
    }

    return 0;
}

