    // Allocate memory for the actual data and copy it
    new_node->data = malloc(data_size);
    if (new_node->data == NULL) {
        perror("Memory allocation failed for data");
        free(new_node);
        return;
    }
    memcpy(new_node->data, new_data, data_size); // Copy the content

    new_node->type = type;
    new_node->next = head;
    head = new_node;
}

// Function to print the list, using the type field for correct casting
void display() {
    struct Node *current = head;
    printf("Generic Linked List:\n");
    while (current != NULL) {
        printf("Data: ");

        // CRITICAL: Cast the void* back to the correct pointer type
        if (current->type == INT) {
            // Cast to int*, then dereference to get the int value
            printf("%d (Integer)", *(int*)current->data);  
        } else if (current->type == STRING) {
            // Cast to char* (or const char*)
            printf("%s (String)", (char*)current->data);
        } else {
            printf("Unknown Type");
        }

        printf("\n");
        current = current->next;
    }
}

// Function to free all allocated memory (prevents memory leaks)
void freeList() {
    struct Node *current = head;
    struct Node *next_node;
    while (current != NULL) {
        next_node = current->next;
        free(current->data); // Free the data block first
        free(current);       // Then free the node block
        current = next_node;
    }
    head = NULL;
}

