    insert(string_val, STRING, strlen(string_val) + 1);  

    // Insert the integer (we pass the address of the integer variable)
    insert(&int_val, INT, sizeof(int));  

    // Demonstrate another integer
    int another_int = 100;
    insert(&another_int, INT, sizeof(int));

    display();

    freeList();

    return 0;
}

