def find_sum_pair(arr, target):
    left, right = 0, len(arr) - 1
    while left < right:
        current_sum = arr[left] + arr[right]
        if current_sum == target:
            print(f"Pair found: ({arr[left]}, {arr[right]})")
            return
        elif current_sum < target:
            left += 1
        else:
            right -= 1
    print("No pair found.")

