def is_valid_nqueens(board):
    n = len(board)
    for i in range(n):
        for j in range(i + 1, n):
            # Check column conflict (should never happen if logic is correct, but safe to check)
            if board[i] == board[j]:
                return False
            # Check diagonal conflict: |col1 - col2| == |row1 - row2|
            if abs(board[i] - board[j]) == abs(i - j):
                return False
    return True

