function delay(time, value) {
    return new Promise(resolve => setTimeout(() => resolve(value), time * 1000));
}

// Array of promises
const promises = [
    delay(1, 1), 
    delay(2, 2), 
    delay(3, 3) // Longest promise determines the total time
];

console.time('Promise.all Time');

Promise.all(promises)
    .then(results => {
        console.log(`All promises resolved: ${results}`);
        console.timeEnd('Promise.all Time');
    })
    .catch(error => console.error("A promise rejected."));

const data = [
    { type: 'A', value: 1 }, 
    { type: 'B', value: 2 }, 
    { type: 'A', value: 3 }
];

const grouped = data.reduce((acc, obj) => {
    const key = obj.type;

    // Check if the key exists, if not, initialize it to an empty array
    if (!acc[key]) {
        acc[key] = [];
    }

    // Push the current object into the array corresponding to its type
    acc[key].push(obj);

    return acc;
}, {}); // Initialize accumulator to an empty object

console.log(grouped);

