function isPrime(n) {
  if (n < 2) return false;
  for (let i = 2; i <= Math.sqrt(n); i++) if (n % i === 0) return false;
  return true;
}
console.log("13 is prime: " + isPrime(13));
console.log("15 is prime: " + isPrime(15));

